CREATE TABLE IF NOT EXISTS security_concepts (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS concept_relationships (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES security_concepts(id), target_id TEXT NOT NULL REFERENCES security_concepts(id), kind TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, UNIQUE(source_id,target_id,kind));
CREATE TABLE IF NOT EXISTS question_concepts (question_id TEXT NOT NULL, revision INTEGER NOT NULL, concept_id TEXT NOT NULL REFERENCES security_concepts(id), PRIMARY KEY(question_id,revision,concept_id), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS question_notebook_policy (question_id TEXT NOT NULL, revision INTEGER NOT NULL, copy_allowed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(question_id,revision), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS misconception_definitions (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_misconceptions (question_id TEXT NOT NULL, revision INTEGER NOT NULL, option_id TEXT NOT NULL, slot INTEGER NOT NULL DEFAULT -1, misconception_id TEXT NOT NULL REFERENCES misconception_definitions(id), weight REAL NOT NULL, status TEXT NOT NULL, PRIMARY KEY(question_id,revision,option_id,slot,misconception_id), FOREIGN KEY(question_id,revision,option_id) REFERENCES question_options(question_id,revision,option_id));
CREATE TABLE IF NOT EXISTS intelligence_processed_attempts (attempt_id TEXT PRIMARY KEY REFERENCES attempts(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, model_version TEXT NOT NULL, unmapped INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS misconception_evidence (attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, misconception_id TEXT NOT NULL REFERENCES misconception_definitions(id), user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, model_version TEXT NOT NULL, polarity INTEGER NOT NULL, weight REAL NOT NULL, independent INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(attempt_id,misconception_id,model_version));
CREATE TABLE IF NOT EXISTS intelligence_content_versions (version INTEGER PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_misconception_states (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, misconception_id TEXT NOT NULL REFERENCES misconception_definitions(id), data TEXT NOT NULL, evaluated_at TEXT NOT NULL, PRIMARY KEY(user_id,misconception_id));
CREATE TABLE IF NOT EXISTS intelligence_policies (version TEXT PRIMARY KEY, data TEXT NOT NULL, created_at TEXT NOT NULL, created_by TEXT);
CREATE TABLE IF NOT EXISTS forecast_snapshots (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES questions(id), model_version TEXT NOT NULL REFERENCES intelligence_policies(version), source_last_at TEXT NOT NULL, forecast_at TEXT NOT NULL, data TEXT NOT NULL, outcome_attempt_id TEXT REFERENCES attempts(id) ON DELETE SET NULL, UNIQUE(user_id,question_id,model_version,source_last_at));
CREATE TABLE IF NOT EXISTS forecast_evaluations (snapshot_id TEXT PRIMARY KEY REFERENCES forecast_snapshots(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, attempt_id TEXT NOT NULL REFERENCES attempts(id) ON DELETE CASCADE, model_version TEXT NOT NULL, predicted REAL, actual INTEGER NOT NULL, error_squared REAL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notebooks (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS notebook_entries (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, notebook_id TEXT REFERENCES notebooks(id) ON DELETE SET NULL, title TEXT NOT NULL, body TEXT NOT NULL, format TEXT NOT NULL DEFAULT 'markdown', category TEXT NOT NULL DEFAULT 'Personal Study Notes', objective TEXT, concept_id TEXT REFERENCES security_concepts(id), question_id TEXT, question_revision INTEGER, source_refs TEXT NOT NULL DEFAULT '[]', study_url TEXT NOT NULL, pinned INTEGER NOT NULL DEFAULT 0, origin_key TEXT, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, UNIQUE(user_id,origin_key), FOREIGN KEY(question_id,question_revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS notebook_tags (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE(user_id,name));
CREATE TABLE IF NOT EXISTS notebook_entry_tags (entry_id TEXT NOT NULL REFERENCES notebook_entries(id) ON DELETE CASCADE, tag_id TEXT NOT NULL REFERENCES notebook_tags(id) ON DELETE CASCADE, PRIMARY KEY(entry_id,tag_id));
CREATE TABLE IF NOT EXISTS notebook_entry_history (entry_id TEXT NOT NULL REFERENCES notebook_entries(id) ON DELETE CASCADE, revision INTEGER NOT NULL, data TEXT NOT NULL, saved_at TEXT NOT NULL, PRIMARY KEY(entry_id,revision));
CREATE TABLE IF NOT EXISTS notebook_mutations (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mutation_id TEXT NOT NULL, entry_id TEXT NOT NULL REFERENCES notebook_entries(id) ON DELETE CASCADE, request_hash TEXT NOT NULL, response TEXT NOT NULL, PRIMARY KEY(user_id,mutation_id));
CREATE INDEX IF NOT EXISTS concept_targets ON concept_relationships(target_id,kind,status);
CREATE INDEX IF NOT EXISTS question_concept_lookup ON question_concepts(concept_id,question_id,revision);
CREATE INDEX IF NOT EXISTS misconception_user_time ON misconception_evidence(user_id,created_at);
CREATE INDEX IF NOT EXISTS processed_user ON intelligence_processed_attempts(user_id,attempt_id);
CREATE INDEX IF NOT EXISTS forecast_user_question ON forecast_snapshots(user_id,question_id,forecast_at);
CREATE INDEX IF NOT EXISTS notes_owner_date ON notebook_entries(user_id,deleted_at,updated_at);
CREATE INDEX IF NOT EXISTS notes_concept ON notebook_entries(user_id,concept_id,deleted_at);
